# -*- coding: utf-8 -*-
"""कठ उपनिषद — अर्थ (अपने शब्दों में, सीधा शब्दार्थ; किसी एक मत का भाष्य नहीं)।

कुंजी "वल्ली.मंत्र" — वल्ली 1–3 पहला अध्याय, 4–6 दूसरा अध्याय।
"""

KATHA = {
    # ── पहला अध्याय, पहली वल्ली ─────────────────────────────────────────────
    '1.1': 'स्वर्ग के फल की इच्छा से वाजश्रवस ने यज्ञ में अपना सारा धन दान कर दिया। उनका नचिकेता नाम का एक पुत्र था।',
    '1.2': 'जब दक्षिणा की गायें ले जाई जा रही थीं, तब उस बालक के मन में श्रद्धा जागी, और वह सोचने लगा —',
    '1.3': '"जो गायें पानी पी चुकीं, घास खा चुकीं, जिनका दूध दुहा जा चुका और जो अब बछड़ा देने लायक़ नहीं रहीं — ऐसी गायों का दान करने वाला उन लोकों में जाता है जिनमें कोई आनंद नहीं।"',
    '1.4': 'उसने पिता से पूछा — "पिताजी, मुझे आप किसे देंगे?" दूसरी बार, तीसरी बार पूछने पर पिता ने झुँझलाकर कह दिया — "तुझे मैं मृत्यु को देता हूँ।"',
    '1.5': '(नचिकेता ने सोचा —) "बहुतों में मैं पहला होकर जा रहा हूँ, बहुतों में बीच का होकर। यम का ऐसा कौन सा काम है जो पिताजी आज मुझसे पूरा कराएँगे?"',
    '1.6': '(उसने पिता से कहा —) "देखिए, आपके पूर्वज कैसे चले, और आज के भले लोग कैसे चलते हैं। मनुष्य अनाज की तरह पकता और झड़ जाता है, और अनाज की तरह ही फिर पैदा होता है।"',
    '1.7': '(नचिकेता यम के घर पहुँचा और तीन रात बिना खाए-पिए बैठा रहा। यम लौटे तो उनसे कहा गया —) "ब्राह्मण अतिथि घर में अग्नि की तरह प्रवेश करता है। उसे शांत करने के लिए लोग यह सत्कार करते हैं — हे सूर्यपुत्र यम, जल ले आइए।"',
    '1.8': '"जिस मंदबुद्धि के घर में ब्राह्मण अतिथि बिना खाए रहता है, उसकी आशा और प्रतीक्षा, सत्संग का फल, मीठी वाणी, यज्ञ और परोपकार के पुण्य, पुत्र और पशु — यह सब नष्ट हो जाता है।"',
    '1.9': '(यम ने कहा —) "हे ब्राह्मण, तुम नमस्कार के योग्य अतिथि हो, और मेरे घर में तीन रात बिना खाए रहे। तुम्हें नमस्कार; मेरा कल्याण हो। इसलिए हर रात के बदले एक — तीन वर माँग लो।"',
    '1.10': '(नचिकेता:) "हे मृत्यु, मेरे पिता गौतम की चिंता शांत हो जाए, उनका मन प्रसन्न हो, मुझ पर उनका क्रोध न रहे; और जब आप मुझे लौटाएँ तो वे मुझे पहचानकर प्रेम से बोलें — तीन वरों में यह पहला वर माँगता हूँ।"',
    '1.11': '(यम:) "मेरी प्रेरणा से तुम्हारे पिता — अरुण के पुत्र उद्दालक — तुम्हें पहले की तरह पहचान लेंगे। तुम्हें मृत्यु के मुख से छूटा हुआ देखकर उनका क्रोध जाता रहेगा, और वे रातों को सुख से सोएँगे।"',
    '1.12': '(नचिकेता:) "स्वर्गलोक में कोई भय नहीं है; वहाँ आप (मृत्यु) नहीं हैं, और न कोई बुढ़ापे से डरता है। भूख और प्यास — दोनों को पार करके, शोक से परे होकर मनुष्य स्वर्गलोक में आनंद करता है।"',
    '1.13': '"हे मृत्यु, आप स्वर्ग दिलाने वाली उस अग्नि को जानते हैं; मुझ श्रद्धा रखने वाले को वह बताइए — जिससे स्वर्ग के लोग अमरता पाते हैं। दूसरे वर से मैं यही माँगता हूँ।"',
    '1.14': '(यम:) "नचिकेता, स्वर्ग दिलाने वाली उस अग्नि को मैं जानता हूँ और तुम्हें बताता हूँ; ध्यान से समझो। वह अनंत लोकों की प्राप्ति कराने वाली और उनका आधार है; और जान लो कि वह हृदय की गुफा में छिपी है।"',
    '1.15': 'यम ने उसे वह अग्नि बताई जो लोकों का आदि-कारण है — वेदी में कौन सी ईंटें लगें, कितनी, और किस तरह। नचिकेता ने सब, जैसा कहा गया था, वैसा ही दोहरा दिया। तब प्रसन्न होकर मृत्यु फिर बोले —',
    '1.16': 'प्रसन्न हुए महात्मा यम ने कहा — "आज मैं तुम्हें एक वर और देता हूँ: यह अग्नि अब तुम्हारे ही नाम से जानी जाएगी। और यह कई रंगों वाली माला भी लो।"',
    '1.17': '"जो तीन बार नाचिकेत अग्नि का चयन करता है, तीनों (माता, पिता और आचार्य) से जुड़ा रहता है और तीन कर्म (यज्ञ, दान, तप) करता है, वह जन्म और मृत्यु को पार कर जाता है। ब्रह्म से उत्पन्न, सब जानने वाले उस पूजनीय देव को जानकर और अनुभव करके वह परम शांति पाता है।"',
    '1.18': '"जो इन तीनों बातों (ईंटें, उनकी गिनती और विधि) को जानकर तीन बार नाचिकेत अग्नि का चयन करता है, वह शरीर छूटने से पहले ही मृत्यु के फंदों को काट देता है, और शोक से परे होकर स्वर्गलोक में आनंद करता है।"',
    '1.19': '"नचिकेता, यह तुम्हारी स्वर्ग दिलाने वाली अग्नि है, जिसे तुमने दूसरे वर से माँगा था। लोग इस अग्नि को तुम्हारे ही नाम से पुकारेंगे। अब तीसरा वर माँगो।"',
    '1.20': '(नचिकेता:) "मरे हुए मनुष्य के बारे में यह जो संदेह है — कोई कहता है कि वह रहता है, कोई कहता है कि नहीं रहता — आपके सिखाने से मैं इसे जान लूँ। वरों में यही मेरा तीसरा वर है।"',
    '1.21': '(यम:) "इस बात पर तो पुराने समय में देवताओं को भी संदेह रहा है। यह विषय बहुत सूक्ष्म है, आसानी से समझ में आने वाला नहीं। नचिकेता, कोई दूसरा वर माँग लो; मुझ पर दबाव मत डालो, मुझे इस वर से छोड़ दो।"',
    '1.22': '(नचिकेता:) "हे मृत्यु, जब देवताओं को भी इस पर संदेह रहा, और आप ख़ुद कहते हैं कि यह आसानी से जानने लायक़ नहीं — तो इसे बताने वाला आप जैसा दूसरा कोई मिल नहीं सकता, और इसके बराबर कोई दूसरा वर नहीं है।"',
    '1.23': '(यम:) "सौ-सौ बरस जीने वाले बेटे-पोते माँग लो; बहुत से पशु, हाथी, सोना और घोड़े माँग लो; धरती का बड़ा राज्य माँग लो — और ख़ुद जितने बरस चाहो, जियो।"',
    '1.24': '"इसके बराबर और कोई वर सूझता हो तो वह भी माँग लो — धन और लंबी आयु। नचिकेता, तुम बड़ी धरती के राजा बनो; मैं तुम्हें सब कामनाओं को भोगने वाला बना देता हूँ।"',
    '1.25': '"मनुष्य-लोक में जो-जो भोग दुर्लभ हैं, वे सब अपनी इच्छा से माँग लो। रथों और बाजों के साथ ये सुंदर स्त्रियाँ — ऐसी मनुष्यों को मिल ही नहीं सकतीं; मैं देता हूँ, इनसे अपनी सेवा कराओ। पर नचिकेता, मरने के बाद की बात मत पूछो।"',
    '1.26': '(नचिकेता:) "हे अंतक (मृत्यु), ये सब भोग कल तक रहेंगे या नहीं, पता नहीं; और ये मनुष्य की सारी इंद्रियों का तेज घिसा देते हैं। पूरा जीवन भी थोड़ा ही है। ये रथ आपके ही पास रहें, यह नाच-गाना भी आपका ही रहे।"',
    '1.27': '"धन से मनुष्य कभी तृप्त नहीं होता। और जब आपके दर्शन हो गए तो धन तो मिल ही जाएगा; जब तक आपका शासन है, हम जीते भी रहेंगे। पर मेरे माँगने लायक़ वर तो वही है।"',
    '1.28': '"नीचे पृथ्वी पर रहने वाला, बूढ़ा होने और मरने वाला मनुष्य — जो कभी बूढ़े न होने वाले अमर देवों के पास पहुँच गया हो और यह सब समझता हो — वह रूप, भोग और मौज-मस्ती का सच सोचकर बहुत लंबे जीवन में भी भला क्या सुख मानेगा?"',
    '1.29': '"हे मृत्यु, जिस बात पर लोग संदेह करते हैं — उस महान परलोक-यात्रा में क्या होता है — वही हमें बताइए। यह वर जो इस गहरे रहस्य तक पहुँचता है — नचिकेता इसके सिवा कोई दूसरा वर नहीं माँगता।"',

    # ── पहला अध्याय, दूसरी वल्ली ────────────────────────────────────────────
    '2.1': '(यम:) "श्रेय — जो सचमुच भला है — एक चीज़ है, और प्रेय — जो प्यारा लगता है — दूसरी। दोनों के लक्ष्य अलग हैं, और दोनों मनुष्य को बाँधते हैं। जो श्रेय को अपनाता है उसका भला होता है; जो प्रेय को चुनता है वह अपने लक्ष्य से चूक जाता है।"',
    '2.2': '"श्रेय और प्रेय — दोनों मनुष्य के सामने आते हैं। समझदार उन दोनों को अच्छी तरह परखकर अलग-अलग पहचानता है, और प्रेय की जगह श्रेय को चुनता है। मंदबुद्धि कमाने और बचाने के मोह में प्रेय को चुनता है।"',
    '2.3': '"नचिकेता, तुमने प्यारे और लुभावने दिखने वाले भोगों को सोच-समझकर छोड़ दिया। तुम धन की उस ज़ंजीर में नहीं फँसे, जिसमें बहुत से मनुष्य डूब जाते हैं।"',
    '2.4': '"जिन्हें अविद्या और विद्या कहा जाता है, वे दोनों एक-दूसरे से बहुत दूर, उलटी और अलग-अलग दिशा में ले जाने वाली हैं। मैं नचिकेता को विद्या का चाहने वाला मानता हूँ — इतने सारे भोग भी तुम्हें ललचा न सके।"',
    '2.5': '"जो अविद्या के भीतर रहते हुए भी अपने को समझदार और पंडित मानते हैं, वे मूढ़ ठोकरें खाते हुए भटकते रहते हैं — जैसे अंधे के पीछे चलते हुए अंधे।"',
    '2.6': '"धन के मोह से अंधे, लापरवाह और नासमझ आदमी को परलोक की बात सूझती ही नहीं। जो मानता है कि बस यही लोक है, दूसरा कोई नहीं — वह बार-बार मेरे वश में आता है।"',
    '2.7': '"जिसके बारे में सुनना भी बहुतों को नहीं मिलता, और सुनकर भी बहुत से जिसे नहीं समझ पाते — उस आत्मा को बताने वाला दुर्लभ है, उसे पाने वाला कोई कुशल ही होता है; और कुशल गुरु से सीखकर उसे जानने वाला भी दुर्लभ है।"',
    '2.8': '"साधारण समझ का आदमी बताए तो यह आत्मा ठीक से समझ में नहीं आता, क्योंकि लोग इसे कई तरह से सोचते हैं। पर जो इसे अपने से अलग नहीं देखता, वह बताए तो कोई संदेह नहीं रहता। यह सूक्ष्म से भी सूक्ष्म है, और तर्क की पहुँच से बाहर।"',
    '2.9': '"प्यारे, यह समझ तर्क से नहीं मिलती; कोई जानने वाला बताए तभी ठीक से आती है। और तुमने वह पा ली है — तुम सचमुच सत्य पर टिके हो। नचिकेता, हमें तुम जैसा पूछने वाला मिलता रहे।"',
    '2.10': '"मैं जानता हूँ कि कर्म-फल का ख़ज़ाना टिकने वाला नहीं है, और टिकाऊ चीज़ अस्थिर साधनों से नहीं मिलती। फिर भी मैंने अस्थिर द्रव्यों से नाचिकेत अग्नि का चयन किया, और यह टिकाऊ पद पाया।"',
    '2.11': '"कामनाओं की पूर्ति, जगत का आधार, यज्ञ का अनंत फल, निर्भयता का दूसरा किनारा, स्तुति के योग्य बड़ी और दूर तक फैली प्रतिष्ठा — नचिकेता, तुमने यह सब देखकर भी समझदारी और धीरज से इसे छोड़ दिया।"',
    '2.12': '"वह पुरातन देव — जिसे देखना कठिन है, जो छिपा हुआ है, भीतर पैठा हुआ है, हृदय की गुफा में और गहराई में बैठा है — उसे अपने भीतर के योग से जानकर समझदार मनुष्य हर्ष और शोक दोनों को छोड़ देता है।"',
    '2.13': '"जो मनुष्य इसे सुनकर ठीक से ग्रहण करता है, और इस सूक्ष्म तत्त्व को शरीर से अलग पहचानकर पा लेता है, वह आनंद के उस स्रोत को पाकर आनंदित होता है। मैं मानता हूँ कि नचिकेता के लिए वह घर खुला हुआ है।"',
    '2.14': '(नचिकेता:) "जो धर्म से परे है और अधर्म से भी, इस कार्य और कारण से परे है, जो बीते हुए और आने वाले से भी परे है — जिसे आप ऐसा देखते हैं, वह मुझे बताइए।"',
    '2.15': '(यम:) "सारे वेद जिस पद को बताते हैं, सारे तप जिसकी बात करते हैं, जिसे चाहकर लोग ब्रह्मचर्य का पालन करते हैं — वह पद मैं तुम्हें थोड़े में बताता हूँ: वह ॐ है।"',
    '2.16': '"यही अक्षर ब्रह्म है, यही अक्षर सबसे ऊँचा है। इसी अक्षर को जानकर जो जो चाहता है, वह उसे मिल जाता है।"',
    '2.17': '"यही सबसे अच्छा सहारा है, यही सबसे ऊँचा सहारा है। इस सहारे को जानकर मनुष्य ब्रह्मलोक में महिमा पाता है।"',
    '2.18': '"यह जानने वाला आत्मा न पैदा होता है, न मरता है। न यह किसी से बना, न इससे कोई बना। यह अजन्मा, नित्य, सदा रहने वाला और पुरातन है; शरीर के मारे जाने पर भी यह नहीं मारा जाता।"',
    '2.19': '"अगर मारने वाला सोचता है कि मैं मार रहा हूँ, और मारा जाने वाला सोचता है कि मैं मारा गया — तो दोनों ही नहीं जानते। यह न मारता है, न मारा जाता है।"',
    '2.20': '"सूक्ष्म से भी सूक्ष्म और बड़े से भी बड़ा यह आत्मा इस प्राणी के हृदय की गुफा में रखा है। जो कामनाओं से छूट गया है, वह मन और इंद्रियों की निर्मलता से आत्मा की उस महिमा को देखता है, और शोक से पार हो जाता है।"',
    '2.21': '"वह बैठा हुआ भी दूर चला जाता है, लेटा हुआ भी सब ओर पहुँच जाता है। उस देव को, जो हर्ष से भरा भी है और हर्ष से रहित भी, मेरे सिवा कौन जान सकता है?"',
    '2.22': '"जो शरीरों में रहकर भी बिना शरीर का है, और बदलती हुई चीज़ों में रहकर भी ठहरा हुआ है — उस महान, सब जगह फैले आत्मा को जानकर समझदार मनुष्य शोक नहीं करता।"',
    '2.23': '"यह आत्मा न प्रवचन से मिलता है, न बुद्धि से, न बहुत सुनने से। जिसे यह स्वयं चुन लेता है, उसी को मिलता है; उसके सामने यह आत्मा अपना स्वरूप खोल देता है।"',
    '2.24': '"जो बुरे आचरण से नहीं हटा, जो शांत नहीं, जिसका मन एकाग्र नहीं, और जिसका चित्त ठहरा नहीं — वह केवल बुद्धि के बल पर इसे नहीं पा सकता।"',
    '2.25': '"ब्राह्मण और क्षत्रिय — दोनों जिसके लिए भात जैसे हैं, और मृत्यु जिसके लिए उस पर की चटनी — वह कहाँ है, यह इस तरह कौन जान सकता है?"',

    # ── पहला अध्याय, तीसरी वल्ली ────────────────────────────────────────────
    '3.1': '"अच्छे कर्मों से मिले इस शरीर में, हृदय की गुफा के सबसे ऊँचे स्थान में दो बैठे हैं, जो कर्म का फल भोगते हैं। ब्रह्म को जानने वाले, पाँच अग्नियों वाले गृहस्थ और तीन बार नाचिकेत अग्नि का चयन करने वाले — सब उन दोनों को छाया और धूप जैसा बताते हैं।"',
    '3.2': '"जो यज्ञ करने वालों के लिए पुल है उस नाचिकेत अग्नि को, और जो पार जाना चाहने वालों के लिए निर्भय किनारा है उस अविनाशी परब्रह्म को — हम दोनों को जान सकें।"',
    '3.3': '"आत्मा को रथ का स्वामी जानो, और शरीर को रथ। बुद्धि को सारथी जानो, और मन को लगाम।"',
    '3.4': '"इंद्रियों को घोड़े कहा गया है, और विषयों को उनके चलने के रास्ते। शरीर, इंद्रियों और मन से जुड़े हुए आत्मा को ही ज्ञानी लोग भोगने वाला कहते हैं।"',
    '3.5': '"जो विवेक से रहित है और जिसका मन सदा बिखरा रहता है, उसकी इंद्रियाँ उसके वश में नहीं रहतीं — जैसे सारथी के बिगड़ैल घोड़े।"',
    '3.6': '"और जो विवेक वाला है, जिसका मन सदा सधा रहता है, उसकी इंद्रियाँ उसके वश में रहती हैं — जैसे सारथी के अच्छे घोड़े।"',
    '3.7': '"जो विवेक से रहित, मन को न सँभालने वाला और सदा अपवित्र रहता है, वह उस पद तक नहीं पहुँचता, और जन्म-मरण के चक्कर में ही पड़ा रहता है।"',
    '3.8': '"और जो विवेक वाला, मन को सँभालने वाला और सदा पवित्र रहता है, वह उस पद को पा लेता है जहाँ से फिर जन्म नहीं होता।"',
    '3.9': '"जिस मनुष्य का सारथी विवेक है और जिसकी लगाम — मन — उसके हाथ में है, वह रास्ते के पार पहुँच जाता है; वही विष्णु का परम पद है।"',
    '3.10': '"इंद्रियों से परे उनके विषय हैं, विषयों से परे मन है, मन से परे बुद्धि है, और बुद्धि से परे महान आत्मा (महत्) है।"',
    '3.11': '"महत् से परे अव्यक्त है, और अव्यक्त से परे पुरुष। पुरुष से परे कुछ नहीं है — वही आख़िरी सीमा है, वही परम गति है।"',
    '3.12': '"यह आत्मा सब प्राणियों में छिपा हुआ है, इसलिए दिखता नहीं। पर सूक्ष्म देखने वाले लोग अपनी पैनी और सूक्ष्म बुद्धि से इसे देख लेते हैं।"',
    '3.13': '"समझदार मनुष्य वाणी को मन में समेटे, मन को बुद्धि में, बुद्धि को महान आत्मा (महत्) में, और उसे शांत आत्मा में समेट दे।"',
    '3.14': '"उठो, जागो, और श्रेष्ठ जनों के पास जाकर इसे समझो। ज्ञानी कहते हैं कि वह रास्ता छुरे की पैनी धार जैसा है — जिस पर चलना कठिन है और जिसे पार करना मुश्किल।"',
    '3.15': '"जो बिना शब्द, बिना स्पर्श और बिना रूप का है, घटता नहीं; बिना रस और बिना गंध का है, नित्य है; जिसका न आदि है न अंत; जो महत् से भी परे और अटल है — उसे जानकर मनुष्य मृत्यु के मुख से छूट जाता है।"',
    '3.16': 'मृत्यु की कही हुई नचिकेता की यह सनातन कथा जो बुद्धिमान सुनाता और सुनता है, वह ब्रह्मलोक में महिमा पाता है।',
    '3.17': 'जो पवित्र होकर इस परम रहस्य को ब्राह्मणों की सभा में या श्राद्ध के समय सुनाता है, उसका वह कर्म अनंत फल देने वाला होता है — अनंत फल देने वाला होता है।',

    # ── दूसरा अध्याय, पहली वल्ली ────────────────────────────────────────────
    '4.1': '(यम:) "स्वयंभू ने इंद्रियों के द्वार बाहर की ओर खोले; इसलिए मनुष्य बाहर की चीज़ें देखता है, भीतर के आत्मा को नहीं। अमरता चाहने वाला कोई धीर पुरुष ही अपनी दृष्टि भीतर मोड़कर अंतरात्मा को देखता है।"',
    '4.2': '"नासमझ लोग बाहर के भोगों के पीछे दौड़ते हैं, और मृत्यु के फैले हुए जाल में फँस जाते हैं। पर धीर लोग अमरता को ही अटल जानकर, यहाँ की अस्थिर चीज़ों में से कुछ नहीं माँगते।"',
    '4.3': '"जिससे मनुष्य रूप, रस, गंध, शब्द, स्पर्श और मिलन के सुख को जानता है — उसी से वह सब कुछ जानता है; फिर यहाँ जानने को क्या बचता है? यही वह है, जिसे तुमने पूछा था।"',
    '4.4': '"जिससे मनुष्य सपने और जागने — दोनों अवस्थाओं की चीज़ें देखता है, उस महान, सब जगह फैले आत्मा को जानकर समझदार शोक नहीं करता।"',
    '4.5': '"जो कर्म-फल का मधु चखने वाले इस जीवात्मा को पास से जान लेता है — कि यही बीते हुए और आने वाले का स्वामी है — वह फिर किसी से डरकर अपने को छिपाता नहीं। यही वह है।"',
    '4.6': '"जो तप से सबसे पहले उत्पन्न हुआ, जो जल से भी पहले पैदा हुआ, और जो हृदय की गुफा में पैठकर प्राणियों के साथ रहता है — जो उसे देखता है, वह उसी ब्रह्म को देखता है। यही वह है।"',
    '4.7': '"जो प्राण के रूप में प्रकट होती है, वह सब देवताओं वाली अदिति — जो हृदय की गुफा में पैठकर रहती है, और प्राणियों के साथ पैदा हुई। यही वह है।"',
    '4.8': '"दो अरणियों (आग मथने की लकड़ियों) के भीतर अग्नि वैसे ही छिपी है जैसे गर्भवती स्त्री के भीतर अच्छी तरह पाला हुआ गर्भ। जागे हुए और हवि देने वाले मनुष्य रोज़ उसकी स्तुति करते हैं। यही वह है।"',
    '4.9': '"जहाँ से सूर्य उगता है और जिसमें वह डूबता है — सब देवता उसी में टिके हैं; उसे कोई लाँघ नहीं सकता। यही वह है।"',
    '4.10': '"जो यहाँ है, वही वहाँ है; जो वहाँ है, वही यहाँ भी है। जो यहाँ अनेकता जैसा कुछ देखता है, वह मृत्यु से मृत्यु की ओर जाता है।"',
    '4.11': '"इसे मन से ही पाया जा सकता है; यहाँ अनेक कुछ भी नहीं है। जो यहाँ अनेकता जैसा कुछ देखता है, वह मृत्यु से मृत्यु की ओर जाता है।"',
    '4.12': '"अँगूठे जितना पुरुष शरीर के बीच, हृदय में रहता है। वह बीते हुए और आने वाले का स्वामी है; उसे जान लेने वाला फिर किसी से डरकर अपने को छिपाता नहीं। यही वह है।"',
    '4.13': '"अँगूठे जितना वह पुरुष बिना धुएँ की ज्योति जैसा है। वह बीते हुए और आने वाले का स्वामी है; वही आज है, वही कल भी रहेगा। यही वह है।"',
    '4.14': '"जैसे ऊँची चोटी पर बरसा पानी पहाड़ों में इधर-उधर बह जाता है, वैसे ही जो चीज़ों को आत्मा से अलग-अलग देखता है, वह उन्हीं के पीछे दौड़ता रहता है।"',
    '4.15': '"जैसे साफ़ पानी में डाला हुआ साफ़ पानी वैसा ही हो जाता है, हे गौतम, वैसे ही जानने वाले मुनि का आत्मा परमात्मा से एक हो जाता है।"',

    # ── दूसरा अध्याय, दूसरी वल्ली ───────────────────────────────────────────
    '5.1': '(यम:) "अजन्मे और सीधी चेतना वाले आत्मा का यह नगर — शरीर — ग्यारह द्वारों वाला है। उसका ध्यान करके मनुष्य शोक नहीं करता, और बंधनों से छूटा हुआ वह सदा के लिए मुक्त हो जाता है। यही वह है।"',
    '5.2': '"वही आकाश में चलने वाला सूर्य (हंस) है, अंतरिक्ष में बसने वाला वायु, वेदी पर बैठा अग्नि, और घर में आया अतिथि। वह मनुष्यों में है, देवताओं में है, सत्य में है, आकाश में है। वह जल में, पृथ्वी पर, यज्ञ में और पहाड़ों पर प्रकट होता है; वही सत्य है, वही महान है।"',
    '5.3': '"वह प्राण को ऊपर ले जाता है और अपान को नीचे फेंकता है। बीच में बैठे उस पूजनीय की सब देवता (इंद्रियाँ) सेवा करते हैं।"',
    '5.4': '"जब शरीर में रहने वाला यह देही शरीर से ढीला होकर अलग हो जाता है, तब यहाँ क्या बचता है? यही वह है।"',
    '5.5': '"कोई भी मनुष्य न प्राण से जीता है, न अपान से। सब किसी और से जीते हैं — जिस पर ये दोनों टिके हैं।"',
    '5.6': '"अच्छा, हे गौतम, अब मैं तुम्हें वह रहस्यमय सनातन ब्रह्म बताता हूँ — और यह भी कि मरने के बाद आत्मा का क्या होता है।"',
    '5.7': '"अपने कर्म और अपने ज्ञान के अनुसार कुछ जीव शरीर धारण करने के लिए किसी गर्भ में जाते हैं, और कुछ पेड़-पौधों जैसे अचल रूप में।"',
    '5.8': '"जब सब सो जाते हैं तब जो पुरुष जागता रहता है और मनचाही चीज़ें रचता जाता है — वही शुद्ध है, वही ब्रह्म है, उसी को अमृत कहते हैं। सब लोक उसी में टिके हैं; उसे कोई लाँघ नहीं सकता। यही वह है।"',
    '5.9': '"जैसे एक ही अग्नि संसार में आकर हर चीज़ के आकार के अनुसार वैसा ही रूप ले लेती है, वैसे ही सब प्राणियों का एक ही अंतरात्मा हर रूप में उसी जैसा हो जाता है — और उनके बाहर भी रहता है।"',
    '5.10': '"जैसे एक ही वायु संसार में आकर हर चीज़ के आकार के अनुसार वैसा ही रूप ले लेती है, वैसे ही सब प्राणियों का एक ही अंतरात्मा हर रूप में उसी जैसा हो जाता है — और उनके बाहर भी रहता है।"',
    '5.11': '"जैसे सूर्य सारे संसार की आँख होकर भी आँखों के बाहरी दोषों से नहीं लिपता, वैसे ही सब प्राणियों का एक अंतरात्मा संसार के दुखों से नहीं लिपता — वह उनसे बाहर है।"',
    '5.12': '"वह एक, सबको वश में रखने वाला, सब प्राणियों का अंतरात्मा — जो अपने एक रूप को अनेक बना लेता है — उसे जो धीर पुरुष अपने भीतर बैठा देखते हैं, सदा रहने वाला सुख उन्हीं को मिलता है, दूसरों को नहीं।"',
    '5.13': '"जो अनित्यों में नित्य है, चेतनों में चेतन है, और अकेला ही बहुतों की कामनाएँ पूरी करता है — उसे जो धीर पुरुष अपने भीतर बैठा देखते हैं, सदा रहने वाली शांति उन्हीं को मिलती है, दूसरों को नहीं।"',
    '5.14': '(नचिकेता:) "ज्ञानी उस परम सुख को — जिसे शब्दों में बताया नहीं जा सकता — यही वह है, कहकर जानते हैं। मैं उसे कैसे जानूँ? क्या वह अपने आप चमकता है, या किसी और के प्रकाश से दिखता है?"',
    '5.15': '(यम:) "वहाँ न सूर्य चमकता है, न चाँद-तारे; न ये बिजलियाँ चमकती हैं — फिर यह आग तो क्या। उसी के चमकने से सब चमकते हैं; उसी के प्रकाश से यह सब प्रकाशित है।"',

    # ── दूसरा अध्याय, तीसरी वल्ली ───────────────────────────────────────────
    '6.1': '(यम:) "यह सनातन पीपल का पेड़ ऐसा है कि जड़ ऊपर है और डालियाँ नीचे। उसकी जो जड़ है, वही शुद्ध है, वही ब्रह्म है, उसी को अमृत कहते हैं। सब लोक उसी में टिके हैं; उसे कोई लाँघ नहीं सकता। यही वह है।"',
    '6.2': '"यह जो कुछ भी जगत है, वह सब प्राण (ब्रह्म) से निकला है और उसी में चल रहा है। वह उठे हुए वज्र जैसा बड़ा भय है। जो उसे जानते हैं, वे अमर हो जाते हैं।"',
    '6.3': '"उसी के भय से अग्नि तपती है, उसी के भय से सूर्य तपता है; उसी के भय से इंद्र, वायु और पाँचवाँ मृत्यु — अपने-अपने काम में दौड़ते हैं।"',
    '6.4': '"अगर मनुष्य शरीर छूटने से पहले यहीं उसे जान सका, तो मुक्त हो जाता है; नहीं तो उसे रचे हुए लोकों में फिर शरीर धारण करना पड़ता है।"',
    '6.5': '"जैसे दर्पण में साफ़ दिखता है, वैसे ही वह अपने भीतर दिखता है; जैसे सपने में, वैसा पितृलोक में; जैसे पानी में झलक सी, वैसा गंधर्वलोक में; और ब्रह्मलोक में छाया और धूप की तरह साफ़ अलग-अलग।"',
    '6.6': '"इंद्रियाँ आत्मा से अलग हैं, अलग-अलग पैदा होती हैं, और उनका जागना और शांत होना भी उन्हीं का है — यह जानकर समझदार मनुष्य शोक नहीं करता।"',
    '6.7': '"इंद्रियों से ऊपर मन है, मन से ऊपर बुद्धि (सत्त्व), बुद्धि से ऊपर महान आत्मा (महत्), और महत् से ऊपर अव्यक्त।"',
    '6.8': '"अव्यक्त से भी परे पुरुष है — सब जगह फैला हुआ, और बिना किसी चिह्न का। उसे जानकर प्राणी मुक्त हो जाता है और अमरता पाता है।"',
    '6.9': '"उसका रूप नज़र के सामने नहीं ठहरता; कोई उसे आँख से नहीं देखता। वह हृदय, बुद्धि और मन से जाना जाता है। जो उसे जानते हैं, वे अमर हो जाते हैं।"',
    '6.10': '"जब पाँचों ज्ञानेंद्रियाँ मन के साथ ठहर जाती हैं, और बुद्धि भी कोई चेष्टा नहीं करती — उसी को परम गति कहते हैं।"',
    '6.11': '"इंद्रियों को इस तरह स्थिर थामे रखने को ही योग माना जाता है। उस समय साधक को सावधान रहना चाहिए, क्योंकि योग आता भी है और चला भी जाता है।"',
    '6.12': '"वह न वाणी से पाया जा सकता है, न मन से, न आँख से। जो कहता है कि वह है — उसके सिवा किसी और को वह कैसे मिल सकता है?"',
    '6.13': '"उसे पहले इसी रूप में जानना चाहिए कि वह है, और फिर उसके असली स्वरूप में। जिसने उसे इतना जान लिया कि वह है, उसके सामने उसका असली स्वरूप अपने आप खुल जाता है।"',
    '6.14': '"जब हृदय में बसी सारी कामनाएँ छूट जाती हैं, तब मरने वाला मनुष्य अमर हो जाता है, और यहीं ब्रह्म को पा लेता है।"',
    '6.15': '"जब यहीं, इसी जीवन में हृदय की सारी गाँठें खुल जाती हैं, तब मरने वाला मनुष्य अमर हो जाता है। उपदेश बस इतना ही है।"',
    '6.16': '"हृदय की एक सौ एक नाड़ियाँ हैं; उनमें से एक सिर की चोटी की ओर निकलती है। उससे ऊपर जाने वाला अमरता पाता है; बाक़ी नाड़ियाँ निकलते समय अलग-अलग दिशाओं में ले जाती हैं।"',
    '6.17': '"अँगूठे जितना पुरुष — अंतरात्मा — सदा लोगों के हृदय में बैठा है। उसे धीरज के साथ अपने शरीर से वैसे ही अलग पहचाने, जैसे मूँज की घास से उसकी सींक निकाली जाती है। उसी को शुद्ध और अमृत जाने — उसी को शुद्ध और अमृत जाने।"',
    '6.18': 'मृत्यु की बताई हुई यह विद्या और योग की पूरी विधि पाकर नचिकेता ब्रह्म को प्राप्त हुआ — मल से रहित और मृत्यु से मुक्त हो गया। और कोई भी, जो अध्यात्म को इसी तरह जान ले, वैसा ही हो जाता है।',
}
